#!/usr/bin/env python3
"""
agent-0232 -- resumable BITPAR reachability BFS over comparator-network output
sets.  Checkpoints so it can run under a short per-invocation wall-clock cap.

Purpose: decide, at n=7, whether any of the non-adjacent candidate penultimate
sets of agent-0232's structure theorem is the output set of ANY comparator
network.  Those sets are
      S(i,j) = SORTED  union  { swap_ij(z_w) : i < n-w <= j },   j >= i+2
one per comparator pair, |S| = n+1+(j-i).  Decided NO at n <= 6 (19,334
reachable output sets, all 94 non-adjacent candidates unreachable).

Usage:
  python3 THIS --selftest
  python3 THIS --n 7 --budget 22 --ckpt /tmp/a0232_n7.bin      # repeat until done
"""
import argparse, os, struct, sys, time
from itertools import combinations


def setup(n):
    N = 1 << n
    comps = list(combinations(range(n), 2))
    pairs = []
    for (i, j) in comps:
        a = 0
        for v in range(N):
            if ((v >> i) & 1) and not ((v >> j) & 1):
                a |= 1 << v
        pairs.append((a, (1 << j) - (1 << i)))
    SORT = 0
    z = {}
    for v in range(N):
        b = [(v >> k) & 1 for k in range(n)]
        if all(b[k] <= b[k + 1] for k in range(n - 1)):
            SORT |= 1 << v
            z[bin(v).count("1")] = v
    return N, comps, pairs, SORT, z


def targets(n, comps, SORT, z):
    """The theorem's candidate penultimate sets, one per comparator pair."""
    out = {}
    for (i, j) in comps:
        s = SORT
        for w in range(n + 1):
            if i < n - w <= j:
                s |= 1 << (z[w] ^ (1 << i) ^ (1 << j))
        out[(i, j)] = s
    return out


def save(path, n, lev, seen, fr, nbytes):
    with open(path, "wb") as fh:
        fh.write(struct.pack("<IIQQ", n, lev, len(seen), len(fr)))
        for s in seen:
            fh.write(s.to_bytes(nbytes, "little"))
        for s in fr:
            fh.write(s.to_bytes(nbytes, "little"))


def load(path, nbytes):
    with open(path, "rb") as fh:
        n, lev, ns, nf = struct.unpack("<IIQQ", fh.read(24))
        blob = fh.read()
    seen = set()
    off = 0
    for _ in range(ns):
        seen.add(int.from_bytes(blob[off:off + nbytes], "little")); off += nbytes
    fr = set()
    for _ in range(nf):
        fr.add(int.from_bytes(blob[off:off + nbytes], "little")); off += nbytes
    return n, lev, seen, fr


def run(n, budget, ckpt):
    N, comps, pairs, SORT, z = setup(n)
    nbytes = (N + 7) // 8
    tgt = targets(n, comps, SORT, z)
    full = (1 << N) - 1
    if ckpt and os.path.exists(ckpt):
        n2, lev, seen, fr = load(ckpt, nbytes)
        assert n2 == n
        print("resumed at level %d with %d states" % (lev, len(seen)))
    else:
        lev, seen, fr = 0, {full}, {full}
    t0 = time.time()
    done = False
    while fr:
        if time.time() - t0 > budget:
            break
        nxt = []
        for s in fr:
            for a, sh in pairs:
                T = s & a
                if T:
                    t = (s ^ T) | (T << sh)
                    if t not in seen:
                        seen.add(t); nxt.append(t)
        lev += 1
        print("level %2d: new=%8d cumulative=%9d  %.1fs"
              % (lev, len(nxt), len(seen), time.time() - t0))
        sys.stdout.flush()
        fr = set(nxt)
        if not nxt:
            done = True
            break
    hits = {str(list(k)): (v in seen) for k, v in tgt.items()}
    adj_hit = {k: v for k, v in hits.items() if eval(k)[1] == eval(k)[0] + 1}
    non_hit = {k: v for k, v in hits.items() if eval(k)[1] != eval(k)[0] + 1}
    print("COMPLETE" if done else "PARTIAL (budget hit)",
          "levels=%d total=%d" % (lev, len(seen)))
    print("adjacent candidate targets reachable so far:", adj_hit)
    print("NON-ADJACENT candidate targets reachable so far:", non_hit)
    print("any non-adjacent reachable:", any(non_hit.values()))
    if ckpt and not done:
        save(ckpt, n, lev, seen, fr, nbytes)
        print("checkpointed to", ckpt, "(%.1f MB)" % (os.path.getsize(ckpt) / 1e6))
    elif ckpt and done and os.path.exists(ckpt):
        print("finished; checkpoint left in place at", ckpt)
    return done, len(seen), non_hit


def selftest():
    ok = True

    def chk(name, cond, got=None):
        nonlocal ok
        print(("  PASS  " if cond else "  FAIL  ") + name +
              ("" if got is None else "  got=%s" % (got,)))
        ok = ok and bool(cond)
    for n, expect in ((3, 7), (4, 44), (5, 581)):
        d, tot, non = run(n, 60, None)
        chk("n=%d BFS completes" % n, d)
        chk("n=%d total reachable output sets = %d" % (n, expect), tot == expect, tot)
        chk("n=%d NO non-adjacent candidate target is reachable" % n,
            not any(non.values()), non)
    print("SELFTEST", "PASS" if ok else "FAIL")
    return 0 if ok else 1


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--selftest", action="store_true")
    ap.add_argument("--n", type=int, default=7)
    ap.add_argument("--budget", type=float, default=22.0)
    ap.add_argument("--ckpt", default=None)
    a = ap.parse_args()
    if a.selftest:
        return selftest()
    run(a.n, a.budget, a.ckpt)
    return 0


if __name__ == "__main__":
    sys.exit(main())

