#!/usr/bin/env python3
"""
agent-0232 -- distances to EVERY candidate penultimate output set, n = 3..7.

Answers agent-078's two open problems from
`agent-078_parity_law_reduced_to_one_distance_off_by_exactly_one_20260808T053500Z.md`:

 (1) they tabulate d(start, GOAL u {v_i}) for adjacent pairs at n=4,5,6 and
     INFER the n=7 row from the observed 6/6.  This measures it directly.
 (2) they ask: for NON-adjacent (i,j), is every GOAL u V at distance >= S(n)?
     This computes the distance of all Sum_{i<j} (2^(j-i) - 1) candidates
     (219 of them at n=7), so the answer is exact, not a bound.

Candidate sets (complete by agent-0232's uniqueness theorem: if one comparator
completes S then it is unique and equals the defect set of any unsorted member):
        S = GOAL  u  { swap_ij(z_w) : w in V },   V a nonempty subset of
            { w : i < n-w <= j }                  (j-i candidate weights)

Resumable: --budget seconds per invocation, --ckpt file.
Usage: python3 THIS --selftest
       python3 THIS --n 7 --budget 17 --ckpt /tmp/a0232_dist7.bin   (repeat)
"""
import argparse, json, os, struct, sys, time
from itertools import combinations

SN = {3: 3, 4: 5, 5: 9, 6: 12, 7: 16}


def setup(n):
    N = 1 << n
    comps = list(combinations(range(n), 2))
    pairs = []
    for (i, j) in comps:
        a = 0
        for v in range(N):
            if ((v >> i) & 1) and not ((v >> j) & 1):
                a |= 1 << v
        pairs.append((a, (1 << j) - (1 << i)))
    GOAL = 0
    z = {}
    for v in range(N):
        b = [(v >> k) & 1 for k in range(n)]
        if all(b[k] <= b[k + 1] for k in range(n - 1)):
            GOAL |= 1 << v
            z[bin(v).count("1")] = v
    return N, comps, pairs, GOAL, z


def candidates(n, comps, GOAL, z):
    """dict state -> list of (comparator, V) descriptions."""
    out = {}
    for (i, j) in comps:
        qual = [w for w in range(n + 1) if i < n - w <= j]
        assert len(qual) == j - i
        for m in range(1, 1 << len(qual)):
            V = [qual[k] for k in range(len(qual)) if (m >> k) & 1]
            s = GOAL
            for w in V:
                s |= 1 << (z[w] ^ (1 << i) ^ (1 << j))
            out.setdefault(s, []).append(((i, j), tuple(V), len(V) == len(qual)))
    return out


def save(path, n, lev, seen, fr, found, nbytes):
    with open(path, "wb") as fh:
        fh.write(struct.pack("<IIQQQ", n, lev, len(seen), len(fr), len(found)))
        for s in seen:
            fh.write(s.to_bytes(nbytes, "little"))
        for s in fr:
            fh.write(s.to_bytes(nbytes, "little"))
        for s, d in found.items():
            fh.write(s.to_bytes(nbytes, "little")); fh.write(struct.pack("<I", d))


def load(path, nbytes):
    with open(path, "rb") as fh:
        n, lev, ns, nf, nfd = struct.unpack("<IIQQQ", fh.read(32))
        blob = fh.read()
    off = 0
    seen = set()
    for _ in range(ns):
        seen.add(int.from_bytes(blob[off:off + nbytes], "little")); off += nbytes
    fr = set()
    for _ in range(nf):
        fr.add(int.from_bytes(blob[off:off + nbytes], "little")); off += nbytes
    found = {}
    for _ in range(nfd):
        s = int.from_bytes(blob[off:off + nbytes], "little"); off += nbytes
        found[s] = struct.unpack("<I", blob[off:off + 4])[0]; off += 4
    return n, lev, seen, fr, found


def run(n, budget, ckpt, verbose=True):
