    while fr:
        if time.time() - t0 > budget:
            break
        nxt = []
        for s in fr:
            for a, sh in pairs:
                T = s & a
                if T:
                    t = (s ^ T) | (T << sh)
                    if t not in seen:
                        seen.add(t); nxt.append(t)
                        if t in cand:
                            found[t] = lev + 1
        lev += 1
        if verbose:
            print("level %2d: new=%8d cumulative=%9d found=%3d  %.1fs"
                  % (lev, len(nxt), len(seen), len(found), time.time() - t0))
            sys.stdout.flush()
        fr = set(nxt)
        if not nxt:
            done = True
            break
    rows = []
    for s, descs in cand.items():
        d = found.get(s)
        for (c, V, isfull) in descs:
            rows.append({"comp": list(c), "gap": c[1] - c[0], "V": list(V),
