def summarise(r):
    n, S = r["n"], r["S_n"]
    adj_full = {}
    non_reach = []
    partial_reach = []
    for x in r["rows"]:
        if x["gap"] == 1 and x["full_V"]:
            adj_full[x["comp"][0]] = x["distance"]
        if x["gap"] >= 2 and x["distance"] is not None:
            non_reach.append(x)
        if not x["full_V"] and x["distance"] is not None:
            partial_reach.append(x)
    row = [adj_full.get(i) for i in range(n - 1)]
    return {
        "n": n, "S_n": S, "complete": r["complete"],
        "reachable_output_sets": r["reachable_output_sets"],
        "adjacent_boundary_and_interior_distances_i_0_to_n_2": row,
        "interior_all_equal_Sn_minus_1": all(d == S - 1 for d in row[1:-1]) if n >= 4 else None,
        "boundary_distances": [row[0], row[-1]],
        "boundary_excess_over_Sn_minus_1": [None if row[0] is None else row[0] - (S - 1),
                                            None if row[-1] is None else row[-1] - (S - 1)],
        "realisable_last_comparators": sorted(i for i, d in adj_full.items() if d == S - 1),
        "non_adjacent_candidates_reachable_at_any_distance": len(non_reach),
        "partial_V_candidates_reachable_at_any_distance": len(partial_reach),
    }


def selftest():
    ok = True

    def chk(name, cond, got=None):
        nonlocal ok
        print(("  PASS  " if cond else "  FAIL  ") + name +
              ("" if got is None else "  got=%s" % (got,)))
        ok = ok and bool(cond)
    exp_sets = {3: 7, 4: 44, 5: 581}
    # agent-078's published table rows
    exp_row = {4: [5, 4, 5], 5: [8, 8, 8, 8]}
    for n in (3, 4, 5):
        r = run(n, 120, None, verbose=False)
        s = summarise(r)
        chk("n=%d BFS complete" % n, s["complete"])
        chk("n=%d reachable output sets = %d" % (n, exp_sets[n]),
            s["reachable_output_sets"] == exp_sets[n], s["reachable_output_sets"])
        chk("n=%d NO non-adjacent candidate reachable at ANY distance" % n,
            s["non_adjacent_candidates_reachable_at_any_distance"] == 0)
        chk("n=%d NO partial-V candidate reachable (Theorem 3: |V| = j-i)" % n,
